def follow_ups_to_the_accountant(apps, schema_editor):
    """AFIT, 2 Nov 2026: follow-ups go to the accountant, one to one, not to the CEO for review. Turn
    shadow mode off, and let follow-ups counted while in shadow (never sent to anyone) start again
    from the first message to the accountant rather than go straight to the team lead."""
    Settings = apps.get_model("coordinator", "CoordinatorSettings")
    AgentCase = apps.get_model("coordinator", "AgentCase")
    AgentAction = apps.get_model("coordinator", "AgentAction")
    AuditEntry = apps.get_model("coordinator", "AuditEntry")
    if not Settings.objects.filter(shadow_mode=True).exists():
        return
    Settings.objects.update(shadow_mode=False)
    reset = 0
    for case in AgentCase.objects.exclude(state="resolved").filter(asked__gt=0):
        if AgentAction.objects.filter(target_id=case.person_id, issue_id=case.issue_id, trigger=case.kind, shadow=False).exists():
            continue
        case.asked, case.last_asked_at = 0, None
        if case.state == "escalated":
            case.state, case.escalated_to = "asked", None
        case.save(update_fields=["asked", "last_asked_at", "state", "escalated_to"])
        reset += 1
    AuditEntry.objects.create(actor=None, action="change settings", target="settings", allowed=True,
                              detail={"before": {"shadow_mode": True}, "after": {"shadow_mode": False},
                                      "note": "Follow-ups go to the accountant one to one (update of 2 Nov 2026).", "cases_restarted": reset})


